import type { ProviderOptions } from '@ai-sdk/provider-utils';
import type { LanguageModel } from 'ai';
import type { JsonSchema7Type } from 'zod-to-json-schema';
import type { AgentMessage, ContentMetadata } from './message';
import type { BuiltTool } from './tool';
import type { AgentEvent, AgentEventHandler } from '../runtime/event';
import type { SerializedMessageList } from '../runtime/message-list';
import type { BuiltTelemetry } from '../telemetry';
import type { JSONValue } from '../utils/json';
export type FinishReason = 'stop' | 'length' | 'content-filter' | 'tool-calls' | 'error' | 'other';
export type TokenUsage<T extends Record<string, unknown> = Record<string, unknown>> = {
    promptTokens: number;
    completionTokens: number;
    totalTokens: number;
    cost?: number;
    inputTokenDetails?: {
        cacheRead?: number;
        cacheWrite?: number;
    };
    outputTokenDetails?: {
        reasoning?: number;
    };
    additionalMetadata?: T;
};
export type ModelConfig = string | {
    id: string;
    apiKey?: string;
    url?: string;
    headers?: Record<string, string>;
} | LanguageModel;
export interface AgentResult {
    id?: string;
    finishReason?: FinishReason;
    usage?: TokenUsage;
    messages: AgentMessage[];
    providerMetadata?: Record<string, unknown>;
    rawResponse?: unknown;
    output?: unknown;
}
export type StreamChunk = ContentMetadata & ({
    type: 'finish';
    finishReason: FinishReason;
    usage?: TokenUsage;
    model?: string;
    structuredOutput?: unknown;
    subAgentUsage?: SubAgentUsage[];
    totalCost?: number;
} | {
    type: 'text-delta';
    id?: string;
    delta: string;
} | {
    type: 'reasoning-delta';
    id?: string;
    delta: string;
} | {
    type: 'tool-call-delta';
    id?: string;
    name?: string;
    argumentsDelta?: string;
} | {
    type: 'error';
    error: unknown;
} | {
    type: 'message';
    message: AgentMessage;
    id?: string;
} | {
    type: 'tool-call-suspended';
    runId?: string;
    toolCallId?: string;
    toolName?: string;
    input?: unknown;
    suspendPayload?: unknown;
    resumeSchema?: JsonSchema7Type;
});
export interface RunOptions {
    persistence?: AgentPersistenceOptions;
}
export interface ExecutionOptions {
    maxIterations?: number;
    abortSignal?: AbortSignal;
    providerOptions?: ProviderOptions;
    telemetry?: BuiltTelemetry;
}
export interface PersistedExecutionOptions {
    maxIterations?: number;
}
export interface ToolResultEntry {
    tool: string;
    input: unknown;
    output: unknown;
    transformed?: boolean;
}
export interface SubAgentUsage {
    agent: string;
    model?: string;
    usage: TokenUsage;
}
export interface GenerateResult {
    runId: string;
    messages: AgentMessage[];
    structuredOutput?: unknown;
    usage?: TokenUsage;
    model?: string;
    finishReason?: FinishReason;
    providerMetadata?: Record<string, unknown>;
    toolCalls?: ToolResultEntry[];
    subAgentUsage?: SubAgentUsage[];
    totalCost?: number;
    pendingSuspend?: Array<{
        runId: string;
        toolCallId: string;
        toolName: string;
        input: unknown;
        suspendPayload: unknown;
        resumeSchema?: JsonSchema7Type;
    }>;
    error?: unknown;
    getState(): SerializableAgentState;
}
export interface StreamResult {
    runId: string;
    stream: ReadableStream<StreamChunk>;
    getState(): SerializableAgentState;
}
export interface ResumeOptions {
    runId: string;
    toolCallId: string;
}
export interface BuiltAgent {
    readonly name: string;
    generate(input: AgentMessage[] | string, options?: RunOptions & ExecutionOptions): Promise<GenerateResult>;
    stream(input: AgentMessage[] | string, options?: RunOptions & ExecutionOptions): Promise<StreamResult>;
    on(event: AgentEvent, handler: AgentEventHandler): void;
    asTool(description: string): BuiltTool;
    abort(): void;
    resume(method: 'generate', data: unknown, options: ResumeOptions & ExecutionOptions): Promise<GenerateResult>;
    resume(method: 'stream', data: unknown, options: ResumeOptions & ExecutionOptions): Promise<StreamResult>;
    approve(method: 'generate', options: ResumeOptions & ExecutionOptions): Promise<GenerateResult>;
    approve(method: 'stream', options: ResumeOptions & ExecutionOptions): Promise<StreamResult>;
    deny(method: 'generate', options: ResumeOptions & ExecutionOptions): Promise<GenerateResult>;
    deny(method: 'stream', options: ResumeOptions & ExecutionOptions): Promise<StreamResult>;
}
export type AgentRunState = 'idle' | 'running' | 'success' | 'failed' | 'suspended' | 'waiting' | 'cancelled';
export interface AgentResumeData {
    resumeToolCall?: {
        toolCallId: string;
    };
    resumeData: unknown;
}
export type PendingToolCall = {
    toolCallId: string;
    toolName: string;
    input: JSONValue;
} & ({
    suspended: true;
    suspendPayload: unknown;
    resumeSchema: JsonSchema7Type;
} | {
    suspended: false;
});
export interface SerializableAgentState {
    persistence?: AgentPersistenceOptions;
    status: AgentRunState;
    messageList: SerializedMessageList;
    resumeData?: AgentResumeData;
    pendingToolCalls: Record<string, PendingToolCall>;
    finishReason?: FinishReason;
    usage?: TokenUsage;
    executionOptions?: PersistedExecutionOptions;
}
export type AgentPersistenceOptions = {
    threadId: string;
    resourceId: string;
};
